using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils;
using Utils.Interface;
using System.Text.Json.Nodes;
namespace Tests;
public class AdminPayoutTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task List_filters_due_totals_snapshot_redaction_and_changed_bank_by_plaintext()
    {
        var admin=await Admin();var user=await LoginPhone("9890000099");Assert.Equal(403,(await user.Get("/api/admin/payouts")).Status);Assert.Equal(422,(await admin.Get("/api/admin/payouts?page=0")).Status);var seller=(await user.Post("/api/seller/register",new{display_name="Synthetic Payout Store"})).Json["id"]!.GetValue<string>();using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var ledger=scope.ServiceProvider.GetRequiredService<LedgerDAL>();var crypto=scope.ServiceProvider.GetRequiredService<EncryptDecrypt>();var enc=crypto.Encrypt("123456789012");await ApiFactory.DbExecAsync("UPDATE sellers SET bank_account_enc=@enc,bank_holder_name='Synthetic Holder',bank_ifsc='SYNT0001234',bank_account_last4='9012' WHERE id=@seller",new{enc,seller});var now=DateTime.UtcNow;var ids=new[]{Guid.NewGuid(),Guid.NewGuid()};await using(var tx=await db.BeginAsync())
        {for(var i=0;i<2;i++)await ledger.InsertPayoutAsync(new(){Id=ids[i],Number="SYNTH-PAYOUT-"+i,SellerId=Guid.Parse(seller),Amount=10000,Status=i==0?"pending":"paid",Mode="manual",BankSnapshot=new JsonObject{["holder"]="Synthetic Holder",["account_enc"]=crypto.Encrypt("123456789012"),["account_last4"]="9012",["ifsc"]="SYNT0001234"}.ToJsonString(),CreatedAt=now.AddMinutes(i),UpdatedAt=now},tx);await tx.CommitAsync();}
        for(var i=0;i<3;i++)await ApiFactory.DbExecAsync("INSERT INTO seller_ledger(id,seller_id,kind,amount,description,available_at,created_at)VALUES(@id,@seller,'adjustment',@amount,'Synthetic',@available,@now)",new{id=Guid.NewGuid(),seller,amount=i==0?1000:i==1?-200:5000,available=i==2?now.AddDays(1):now.AddSeconds(-1),now});var r=await admin.Get("/api/admin/payouts");Assert.True(r.Status==200,r.ToString());Assert.Equal(2,r.Json["total"]!.GetValue<long>());Assert.Equal(800,r.Json["due"]![0]!["amount"]!.GetValue<long>());Assert.Equal("paid",r.Json["items"]![0]!["status"]!.GetValue<string>());Assert.Equal("Synthetic Payout Store",r.Json["items"]![1]!["seller_name"]!.GetValue<string>());Assert.False(r.Json["items"]![1]!["bank_changed"]!.GetValue<bool>());Assert.Null(r.Json["items"]![1]!["bank"]!["account_enc"]);Assert.DoesNotContain("123456789012",r.ToString());Assert.Single((await admin.Get("/api/admin/payouts?status=pending&seller_id="+seller)).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/payouts?seller_id="+Guid.NewGuid())).Json["items"]!.AsArray());Assert.Equal(2,(await admin.Get("/api/admin/payouts?status=")).Json["total"]!.GetValue<long>());
        enc=crypto.Encrypt("123456780000");await ApiFactory.DbExecAsync("UPDATE sellers SET bank_account_enc=@enc WHERE id=@seller",new{enc,seller});r=await admin.Get("/api/admin/payouts");Assert.True(r.Json["items"]![1]!["bank_changed"]!.GetValue<bool>());Assert.False(r.Json["items"]![0]!["bank_changed"]!.GetValue<bool>());await ApiFactory.DbExecAsync("UPDATE payouts SET bank_snapshot=JSON_OBJECT('holder','Legacy') WHERE id=@id",new{id=ids[0]});r=await admin.Get("/api/admin/payouts?status=pending");Assert.False(r.Json["items"]![0]!["bank_changed"]!.GetValue<bool>());Assert.Equal(50,r.Json["page_size"]!.GetValue<int>());
        Assert.Equal(403,(await user.Post("/api/admin/payouts/"+ids[0]+"/cancel",new{})).Status);Assert.Equal(409,(await admin.Post("/api/admin/payouts/"+Guid.NewGuid()+"/cancel",new{})).Status);Assert.Equal(404,(await admin.Post("/api/admin/payouts/"+Guid.NewGuid()+"/paid",new{utr="SYNTH1234"})).Status);Assert.Equal(422,(await admin.Post("/api/admin/payouts/"+ids[0]+"/paid",new{utr="bad"})).Status);Assert.Equal(409,(await admin.Post("/api/admin/payouts/"+ids[1]+"/use-current-bank",new{})).Status);
        r=await admin.Post("/api/admin/payouts/"+ids[0]+"/use-current-bank",new{});Assert.True(r.Status==200,r.ToString());Assert.Equal("0000",r.Json["bank"]!["account_last4"]!.GetValue<string>());Assert.False(r.Json["bank_changed"]!.GetValue<bool>());Assert.Null(r.Json["bank"]!["account_enc"]);
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_payout_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='payout.paid' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic payout rollback'; END IF; END");try{Assert.Equal(500,(await admin.Post("/api/admin/payouts/"+ids[0]+"/paid",new{utr="SYNTH1234"})).Status);Assert.Equal("pending",await ApiFactory.DbScalarAsync<string>("SELECT status FROM payouts WHERE id=@id",new{id=ids[0]}));Assert.Equal(0,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM notifications WHERE event='payout_sent'"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_payout_fail");}
        r=await admin.Post("/api/admin/payouts/"+ids[0]+"/paid",new{utr="SYNTH1234"});Assert.True(r.Status==200,r.ToString());Assert.Equal("paid",r.Json["status"]!.GetValue<string>());Assert.Equal("SYNTH1234",r.Json["utr"]!.GetValue<string>());Assert.NotNull(r.Json["paid_at"]);Assert.True(await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM notifications WHERE event='payout_sent'")>0);Assert.Equal(409,(await admin.Post("/api/admin/payouts/"+ids[0]+"/paid",new{utr="SYNTH5678"})).Status);
        Assert.Equal(403,(await user.Get("/api/admin/payouts/bank-file.csv")).Status);await ApiFactory.DbExecAsync("UPDATE payouts SET status='pending',mode='manual' WHERE id=@id",new{id=ids[0]});await ApiFactory.DbExecAsync("UPDATE payouts SET bank_snapshot=JSON_OBJECT('holder','=Synthetic, \"Holder\"','account_enc',@enc,'account_last4','0000','ifsc','SYNT0001234') WHERE id=@id",new{id=ids[0],enc});await ApiFactory.DbExecAsync("UPDATE sellers SET bank_holder_name='=Synthetic, \"Holder\"' WHERE id=@seller",new{seller});var csv=await admin.Get("/api/admin/payouts/bank-file.csv");Assert.True(csv.Status==200,csv.ToString());Assert.Contains("123456780000",csv.Text);Assert.Contains("100.00",csv.Text);Assert.Contains("\"'=Synthetic, \"\"Holder\"\"\"",csv.Text);Assert.DoesNotContain("SYNTH-PAYOUT-1",csv.Text);await ApiFactory.DbExecAsync("UPDATE sellers SET bank_ifsc='SYNT0009999' WHERE id=@seller",new{seller});csv=await admin.Get("/api/admin/payouts/bank-file.csv");Assert.DoesNotContain("SYNTH-PAYOUT-0",csv.Text);await ApiFactory.DbExecAsync("UPDATE sellers SET bank_ifsc='SYNT0001234' WHERE id=@seller",new{seller});
        var orders=scope.ServiceProvider.GetRequiredService<OrdersDAL>();var oid=Guid.NewGuid();var subs=new[]{Guid.NewGuid(),Guid.NewGuid()};await using(var tx=await db.BeginAsync()){await orders.InsertOrderAsync(new(){Id=oid,Number="SYNTH-PAYOUT-ORDER",UserId=Guid.Parse(user.Id),Status="placed",PaymentMethod="cod",PaymentStatus="cod",ShipTo="{}",ItemsTotal=20000,GrandTotal=20000,Currency="INR",FxRate=1,Fees="[]",IdempotencyKey=Guid.NewGuid().ToString(),CreatedAt=now,UpdatedAt=now},tx);for(var i=0;i<2;i++)await orders.InsertSubOrderAsync(new(){Id=subs[i],OrderId=oid,SellerId=Guid.Parse(seller),Number="SYNTH-PAYOUT-SUB-"+i,Status="delivered",ItemsTotal=10000,Total=10000,SettlementStatus="paid",CreatedAt=now,UpdatedAt=now},tx);await tx.CommitAsync();}for(var i=0;i<2;i++)await ApiFactory.DbExecAsync("INSERT INTO seller_ledger(id,seller_id,sub_order_id,kind,amount,description,available_at,payout_id,created_at)VALUES(@id,@seller,@sub,'sale',1000,'Synthetic sale',@now,@payout,@now)",new{id=Guid.NewGuid(),seller,sub=subs[i],payout=ids[i],now});
        await ApiFactory.DbExecAsync("UPDATE payouts SET status='pending' WHERE id=@id",new{id=ids[0]});await ApiFactory.DbExecAsync("UPDATE seller_ledger SET payout_id=@id WHERE amount=1000 AND payout_id IS NULL",new{id=ids[0]});r=await admin.Post("/api/admin/payouts/"+ids[0]+"/cancel",new{});Assert.True(r.Status==200,r.ToString());Assert.Equal("cancelled",r.Json["status"]!.GetValue<string>());Assert.Equal("Cancelled by admin",r.Json["failure_reason"]!.GetValue<string>());Assert.Equal(0,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM seller_ledger WHERE payout_id=@id",new{id=ids[0]}));Assert.Equal(409,(await admin.Post("/api/admin/payouts/"+ids[0]+"/cancel",new{})).Status);Assert.Equal(409,(await admin.Post("/api/admin/payouts/"+ids[0]+"/paid",new{utr="SYNTH5678"})).Status);Assert.Equal("pending",await ApiFactory.DbScalarAsync<string>("SELECT settlement_status FROM sub_orders WHERE id=@id",new{id=subs[0]}));Assert.Equal("paid",await ApiFactory.DbScalarAsync<string>("SELECT settlement_status FROM sub_orders WHERE id=@id",new{id=subs[1]}));Assert.Equal(1,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM seller_ledger WHERE payout_id=@id",new{id=ids[1]}));

    }
}
